import{_ as r,o as d,c as e,a2 as a}from"./chunks/framework.BXzK3EA4.js";const f=JSON.parse('{"title":"《잔선: 서울》","description":"","frontmatter":{},"headers":[],"relativePath":"design/Home.md","filePath":"design/Home.md"}'),o={name:"design/Home.md"};function l(n,t,h,s,i,m){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="《잔선-서울》" tabindex="-1">《잔선: 서울》 <a class="header-anchor" href="#《잔선-서울》" aria-label="Permalink to &quot;《잔선: 서울》&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-home.svg?raw=true" alt="잔선 서울의 인물 방향 시야 아이소 개요"></p><p>홈 화면에서 4방향 시야와 인물 위치를 한눈에 파악해 즉시 탐색 방향을 결정합니다.</p><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/janseon-seoul-cover.png?raw=true" alt="붕괴 이후 지하철 거점의 콘셉트"></p><blockquote><p><strong>붕괴한 서울의 지하철망에서 무명 인물과 파티를 이끌어 역과 노선의 새로운 질서를 세우는 4X + RPG — 전투는 4방향 격자 위의 실시간 진형·카드 전투.</strong></p></blockquote><p>《잔선: 서울》은 아포칼립스 이후 서울의 지하철망을 영토·물류·생존·정통성의 골격으로 삼는 인물 중심 대전략 RPG입니다. 플레이어는 무명 인물입니다. 소규모 파티로 시작해 역과 노선을 오가며 생업, 관계, 직위와 세력 내 영향력을 쌓습니다. 탐색, 상호작용과 전투는 하나의 고정 직교 아이소메트릭 카메라와 4방향 타일 격자를 공유합니다.</p><h2 id="문서-안내" tabindex="-1">문서 안내 <a class="header-anchor" href="#문서-안내" aria-label="Permalink to &quot;문서 안내&quot;">​</a></h2><table tabindex="0"><thead><tr><th>문서</th><th>설명</th></tr></thead><tbody><tr><td><a href="/design/Game-Thesis.html">이 게임이 뭔지</a></td><td>어떤 인물로 시작해 무엇을 이루는 게임인지</td></tr><tr><td><a href="/world/World-and-Subway-Layers.html">서울과 지하철 레이어</a></td><td>다층 세계 그래프와 데이터 출처</td></tr><tr><td><a href="/world/World-Map-Construction.html">월드맵을 어떻게 구성하나</a></td><td>구 25·역 목록·시설을 그래프로 조립하는 순서. 런타임은 세 역</td></tr><tr><td><a href="/world/Seoul-Station-Catalog.html">서울 역 카탈로그</a></td><td>OSM에서 뽑은 서울 안 이름 있는 역 334곳</td></tr><tr><td><a href="/world/Station-Interior-Construction.html">역 내부에 들어가면</a></td><td>입장 시 층·격자·시설 슬롯. 조우 정산 API와 별개</td></tr><tr><td><a href="/rules/Campaign-Loop.html">출격하고 돌아오는 흐름</a></td><td>준비, 원정, 마주침, 전투, 복귀와 결과 반영</td></tr><tr><td><a href="/world/Strongholds-and-Territory.html">거점과 영토</a></td><td>점령, 안정화, 통합, 시설과 영토 과확장</td></tr><tr><td><a href="/world/Economy-and-Production.html">경제와 생산</a></td><td>생존 자원, 노동, 전력, 생산과 시장 가격</td></tr><tr><td><a href="/world/Logistics-and-Infrastructure.html">물류와 기반 시설</a></td><td>허가된 경로, 처리량, 비축, 고립과 복구</td></tr><tr><td><a href="/world/Factions-and-Diplomacy.html">세력과 외교</a></td><td>신뢰, 평판, 정통성, 협약과 집단 불만</td></tr><tr><td><a href="/rules/Warfare-and-Sieges.html">전쟁과 공성</a></td><td>접근로, 보급, 봉쇄, 철수와 점령 후 유지</td></tr><tr><td><a href="/rules/Campaign-Progression.html">캠페인 진행과 위기</a></td><td>안정화, 전문화, 긴장도, 회복과 다중 결말</td></tr><tr><td><a href="/world/Characters-Factions-and-Professions.html">인물·세력·생업</a></td><td>관계, 직위, 정통성과 성장</td></tr><tr><td><a href="/world/Sixteen-States.html">서울 십육국</a></td><td>총16국, 강국5·약소국11의 지리와 기반시설</td></tr><tr><td><a href="/world/Core-Characters.html">십육국 핵심 인물</a></td><td>국가별 핵심 인물의 성격, 야망, 공포와 촉발 사건</td></tr><tr><td><a href="/world/Cast-Index.html">인물 총람</a> · <a href="/world/Cast-Relations.html">관계 원장</a></td><td>16국 인물 412명과 인물 사이 관계 원장</td></tr><tr><td><a href="/world/Cast-Profile-Contract.html">인물 카드 계약</a></td><td>이름 있는 인물의 필수 칸. 출신·언어·징집·무장 접근</td></tr><tr><td><a href="/world/Hangnyeol-and-Bon-gwan.html">본관과 항렬</a> · <a href="/world/Random-Cast-Roster.html">랜덤 추가 로스터</a></td><td>성·남·여 풀 분리, 본관 항렬, Nemotron 100명 롤</td></tr><tr><td><a href="/world/Conscription-Remnants.html">징집 잔존과 군 장부</a></td><td>징병제 명부가 동원잔존·무기고·탈영으로 쪼개지는 방식</td></tr><tr><td><a href="/world/Diaspora-Corridors.html">이주민 회랑</a> · <a href="/world/Cast-Corridors-Index.html">회랑 인물</a></td><td>대림·구로공단·이태원·용산 위에 얹는 다국적 회랑과 시드 인물</td></tr><tr><td><a href="/world/Ambitions-and-Relations.html">야망과 관계가 움직이는 정치</a></td><td>이름 있는 인물이 동맹, 배신, 전쟁과 계승을 만드는 규칙</td></tr><tr><td><a href="/world/Heirs-Names-and-World-Ledger.html">후계, 이름 로스터, 세계 원장</a></td><td>문화 성명 풀에서 후계를 만들고, 면담·거래가 세계 사건에 쌓이는 규칙</td></tr><tr><td><a href="/world/Scenario-Timeline.html">시나리오 타임라인</a></td><td>붕괴 이전부터 패권전까지 조건에 따라 갈라지는 연대기</td></tr><tr><td><a href="/world/Era-Arms-and-Tech-Level.html">이 시대의 기술과 무구</a></td><td>2026 기술에서 붕괴 이후 생업 공구·제식·군용 잔존·로스트 회수</td></tr><tr><td><a href="/world/World-Narrative-Atlas.html">세계 서사 지도</a></td><td>가문·적대 생태·몬스터·서사 배치의 원본</td></tr><tr><td><a href="/rules/Travel-and-Encounters.html">이동과 조우</a></td><td>4방향 행동과 원정 위험</td></tr><tr><td><a href="/rules/Realtime-Formation-Card-Battle.html">실시간 진형·카드 전투</a></td><td>같은 격자에서 이어지는 실시간 진형·카드 전투 (Core 규칙 버전 <code>rtfc-owner-cards-v2</code>)</td></tr><tr><td><a href="/rules/Strategy-Battle-Roundtrip.html">전략에서 전투로</a></td><td>세계 상태를 전투에 넘기고 결과를 한 번만 반영하는 법</td></tr><tr><td><a href="/rules/Character-Art-Direction.html">캐릭터 미술</a></td><td>2.5등신 전술 실루엣과 인물 프로필 초상 규칙</td></tr><tr><td><a href="/design/Asset-Pipeline.html">에셋이 들어오는 길</a></td><td>의도 JSON을 그래프로 컴파일·검사하고 생성부터 승인까지 가는 설명서</td></tr><tr><td><a href="/design/Ui-Implementation-Pipeline.html">UI가 코드로 들어오는 길</a></td><td>HTML 목업을 먼저 고정한 뒤 uGUI로 옮기는 화면 경로</td></tr><tr><td><a href="/rules/Unity-Architecture.html">유니티 구조</a></td><td>규칙과 화면을 나누는 영역별 책임</td></tr><tr><td><a href="/rules/Unity-System-Design.html">Unity 시스템 설계 계약</a></td><td>FSM, VContainer, Singleton과 Repository의 구현 전 계약</td></tr><tr><td><a href="/rules/Unity-Architecture-Implementation-Plan.html">Unity 아키텍처 구현 계획</a></td><td>계약을 RED→GREEN으로 적용하고 검증하는 순서</td></tr><tr><td><a href="/rules/Save-and-Determinism.html">같은 선택이 같은 결과가 되나</a></td><td>같은 상황을 다시 만들 수 있는 안전한 저장</td></tr><tr><td><a href="/design/Development-Roadmap.html">개발 로드맵</a></td><td>검증 게이트와 구현 순서</td></tr></tbody></table><h2 id="현재-구현-범위" tabindex="-1">현재 구현 범위 <a class="header-anchor" href="#현재-구현-범위" aria-label="Permalink to &quot;현재 구현 범위&quot;">​</a></h2><p>현재 모듈 <code>Unity POC 통합 코어 루프</code>까지 구현되어 있습니다. 이 모듈은 <code>Bootstrap</code> App scope/FSM, 배타적 <code>MainTitle</code>/<code>Foundation</code> 화면 lease, uGUI 화면, 세 역 노선과 교섭·우회·전투·정산·복귀를 구현했고, 전투 Core는 30Hz 고정 틱의 실시간 진형·카드 규칙(<code>rtfc-owner-cards-v2</code>)입니다. 동일 seed 재현과 중복 정산 거부를 실제 batchmode PlayMode에서 검증했습니다.</p><p>생성 아트 슬롯은 아직 런타임 화면에 연결되지 않았습니다. 아트 슬롯 승인·연결은 별도 수용 조건이며, 코드 검증만으로 모듈 전체가 완료되지는 않습니다. 16국 캠페인 시뮬레이션, 집계 사상자 표현, <code>ToDo.md</code>의 13–17 항목은 아직 완료가 아니며 이 문서에 정의된 검증 게이트를 따라 이후 구현합니다. 문서에 적힌 설계는 구현 완료를 의미하지 않습니다.</p>',11)])])}const p=r(o,[["render",l]]);export{f as __pageData,p as default};
